import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();

        s = replaceAtFirst(s, "at", "@");

        if (s.charAt(0) == '@') {
            s = "at" + replaceAtFirst(s.substring(1), "at", "@");
        }

        if (s.contains("dot")) {
            s = s.replace("dot", ".");
            if (s.startsWith(".")) {
                s = "dot" + s.substring(1);
            }
            if (s.endsWith(".")) {
                s = s.substring(0, s.length() - 1) + "dot";
            }
        }

        System.out.println(s);
        scanner.close();
    }

    private static String replaceAtFirst(String s, String target, String replacement) {
        int index = s.indexOf(target);
        if (index == -1) {
            return s;
        }
        return s.substring(0, index) + replacement + s.substring(index + target.length());
    }
}
